(()=>{
 const dialog=$('#calendar-dialog');let suggestions=[],saving=false;
 function open(){if(document.querySelector('dialog[open]')){toast('Close the current window first.');return}dialog.showModal()}
 $('#open-calendar').onclick=open;
 $('#calendar-timezone').textContent='Times use '+(globalThis.thisDevice||'this Mac')+'’s time zone: '+Intl.DateTimeFormat().resolvedOptions().timeZone+'. No invitation or email text is included.';
 function localDate(text){const d=new Date(text);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
 async function refresh(action='calendarList'){try{const result=await bridge(action);window.dispatchEvent(new CustomEvent('calendar-updated',{detail:result.events}));$('#calendar-destination').innerHTML='<option value="">Choose a calendar</option>'+result.calendars.map(c=>`<option value="${escape(c.id)}">${escape(c.title)}</option>`).join('');$('#calendar-events').innerHTML=result.events.length?result.events.map(e=>`<div class="calendar-event"><strong>${escape(e.title)}</strong><span>${escape(new Date(e.start).toLocaleString())}${e.allDay?' · All day':''} · ${escape(e.calendar)}</span></div>`).join(''):'Nothing scheduled in the next 30 days.'}catch(e){toast(e.message)}}
 $('#calendar-connect').onclick=()=>refresh('calendarConnect');$('#calendar-refresh').onclick=()=>refresh();
 async function detect(items){try{const result=await bridge('calendarSuggest',{items});suggestions=result.suggestions;$('#calendar-suggestions').innerHTML=suggestions.length?'<h3>Buddy spotted these dates</h3>'+suggestions.map((s,i)=>`<button type="button" data-meeting="${i}"><strong>${escape(s.title||'Meeting')}</strong><span>${escape(s.phrase)} · ${escape(new Date(s.start).toLocaleString())}</span><small>Review →</small></button>`).join(''):'No upcoming dates found. You can enter a meeting below.'}catch(e){toast(e.message)}}
 $('#calendar-scan').onclick=()=>detect(mails.filter(m=>m.folder==='inbox').slice(0,40).map(m=>({title:m.subject,text:m.body,source:String(m.id)})));
 $('#calendar-chat-scan').onclick=()=>detect([{title:'Meeting from chat',text:$('#calendar-chat').value,source:'chat'}]);
 $('#calendar-suggestions').onclick=e=>{const button=e.target.closest('[data-meeting]');if(!button)return;const suggestion=suggestions[Number(button.dataset.meeting)];if(!suggestion)return;$('#calendar-title').value=suggestion.title||'Meeting';$('#calendar-start').value=localDate(suggestion.start);$('#calendar-end').value=localDate(suggestion.end)};
 $('#calendar-event-form').onsubmit=async e=>{e.preventDefault();if(saving)return;saving=true;$('#calendar-save').disabled=true;try{await bridge('calendarCreate',{title:$('#calendar-title').value,start:new Date($('#calendar-start').value).toISOString(),end:new Date($('#calendar-end').value).toISOString(),calendarID:$('#calendar-destination').value});toast('Event added to your calendar.');$('#calendar-title').value='';$('#calendar-start').value='';$('#calendar-end').value='';await refresh()}catch(e){toast(e.message)}finally{saving=false;$('#calendar-save').disabled=false}};
 window.receiveMeetingText=text=>{if(document.querySelector('dialog[open]')!==dialog&&document.querySelector('dialog[open]')){toast('Close the current dialog, then select the chat text again.');return}if(!dialog.open)dialog.showModal();$('#calendar-chat').value=String(text).slice(0,6000);detect([{title:'Meeting from chat',text:String(text).slice(0,6000),source:'chat'}])};
 window.addEventListener('mail-account-changed',()=>{suggestions=[];$('#calendar-suggestions').innerHTML='';$('#calendar-chat').value='';$('#calendar-title').value='';dialog.close()});
})();
